import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        final int N = 20;
        final double eps = 1e-10;
        int n = sc.nextInt();
        int k = sc.nextInt();
        double[] a = new double[N];
        double[] p = new double[1 << N];
        double[] res = new double[N];

        int cnt = 0;
        for (int i = 0; i < n; i++) {
            a[i] = sc.nextDouble();
            if (a[i] < eps) cnt++;
        }
        k = Math.min(n - cnt, k);
        p[0] = 1.0;

        for (int mask = 1; mask < (1 << n); mask++) {
            double suma = 0.0;
            boolean ok = true;
            int cntBits = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) {
                    suma += a[i];
                    if (a[i] < eps) ok = false;
                    cntBits++;
                }
            }
            if (!ok) {
                p[mask] = 0.0;
                continue;
            } else {
                double sump = 0.0;
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        double denom = 1 - suma + a[i];
                        if (denom != 0) {
                            sump += (a[i] / denom) * p[mask ^ (1 << i)];
                        }
                    }
                }
                p[mask] = sump;
            }
            if (cntBits == k) {
                for (int i = 0; i < n; i++) {
                    if ((mask & (1 << i)) != 0) {
                        res[i] += p[mask];
                    }
                }
            }
        }

        for (int i = 0; i < n; i++) {
            System.out.printf("%.10f%s", res[i], (i == n - 1) ? "\n" : " ");
        }
        sc.close();
    }
}
